insert into change_headers (id, ts) values (77, '2026-11-21') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (77, 'ru', 'Числа во всех калькуляторах теперь записываются по правилам языка сайта: в русской версии разряды разделяются пробелом (1 234 567), дробь — запятой, в том числе в сокращённой форме (1,5М). Для триллионов добавлено сокращение Т (1,234Т).<br>Время меньше суток показывается часами — 05:49:42, а сроки от года — в годах, месяцах и неделях (1г 3мес 2нд) вместо сотен недель.<br>Французская версия Расчёта стоимости снова работает.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'en', 'Numbers in every calculator are now written the way the site language writes them: in the English version thousands are grouped with a comma (1,234,567) and the fraction follows a dot, the short form included (1.5M). Trillions get their own abbreviation, T (1.234T).<br>A time under a day is shown as a clock - 05:49:42 - and a span of a year or more in years, months and weeks (1y 3mo 2w) instead of hundreds of weeks.<br>The French version of the Costs calculator works again.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'pt', 'Os números de todas as calculadoras passam a ser escritos segundo as regras da língua do site: na versão portuguesa os milhares são separados por um espaço (1 234 567) e as casas decimais por uma vírgula, também na forma abreviada (1,5M). Os biliões passam a ter a sua própria abreviatura, T (1,234T).<br>Um tempo inferior a um dia é mostrado como relógio - 05:49:42 - e um prazo de um ano ou mais em anos, meses e semanas (1a 3m 2w) em vez de centenas de semanas.<br>A versão francesa da calculadora de custos volta a funcionar.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'de', 'Zahlen werden in allen Rechnern jetzt so geschrieben, wie es in der Sprache der Seite üblich ist: in der deutschen Version trennt ein Punkt die Tausender (1.234.567) und ein Komma die Nachkommastellen, auch in der Kurzform (1,5M). Für Billionen gibt es eine eigene Abkürzung, T (1,234T).<br>Eine Zeit unter einem Tag wird als Uhrzeit angezeigt - 05:49:42 -, eine Dauer ab einem Jahr in Jahren, Monaten und Wochen (1j 3mo 2w) statt in Hunderten von Wochen.<br>Die französische Version des Kostenrechners funktioniert wieder.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'pl', 'Liczby we wszystkich kalkulatorach są teraz zapisywane zgodnie z zasadami języka strony: w polskiej wersji tysiące oddziela spacja (1 234 567), a część ułamkową przecinek, także w formie skróconej (1,5M). Biliony mają własny skrót, T (1,234T).<br>Czas krótszy niż doba jest pokazywany jako zegar - 05:49:42 - a okres od roku wzwyż w latach, miesiącach i tygodniach (1r 3mies 2td) zamiast setek tygodni.<br>Francuska wersja kalkulatora kosztów znów działa.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'es', 'Los números de todas las calculadoras se escriben ahora según las normas del idioma del sitio: en la versión española los millares se separan con un punto (1.234.567) y los decimales con una coma, también en la forma abreviada (1,5M). Los billones tienen su propia abreviatura, T (1,234T).<br>Un tiempo inferior a un día se muestra como un reloj - 05:49:42 - y un plazo de un año o más en años, meses y semanas (1a 3m 2sm) en lugar de cientos de semanas.<br>La versión francesa de la calculadora de costes vuelve a funcionar.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'fr', 'Dans tous les calculateurs, les nombres s''écrivent désormais selon les règles de la langue du site : dans la version française, les milliers sont séparés par une espace fine (1 234 567) et les décimales par une virgule, y compris dans la forme abrégée (1,5M). Les billions ont leur propre abréviation, T (1,234T).<br>Une durée de moins d''un jour s''affiche comme une horloge - 05:49:42 - et une durée d''un an ou plus en années, mois et semaines (1a 3m 2sm) au lieu de centaines de semaines.<br>La version française du calculateur de coûts fonctionne de nouveau.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'it', 'In tutti i calcolatori i numeri ora sono scritti secondo le regole della lingua del sito: nella versione italiana le migliaia sono separate da un punto (1.234.567) e i decimali da una virgola, anche nella forma abbreviata (1,5M). I bilioni hanno una propria abbreviazione, T (1,234T).<br>Un tempo inferiore a un giorno è mostrato come un orologio - 05:49:42 - e una durata di un anno o più in anni, mesi e settimane (1a 3me 2st) invece che in centinaia di settimane.<br>La versione francese del calcolatore dei costi funziona di nuovo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'nl', 'Getallen worden in alle calculators nu geschreven volgens de regels van de taal van de site: in de Nederlandse versie scheidt een punt de duizendtallen (1.234.567) en een komma de decimalen, ook in de verkorte vorm (1,5M). Biljoenen krijgen een eigen afkorting, T (1,234T).<br>Een tijd korter dan een dag wordt als klok getoond - 05:49:42 - en een duur van een jaar of langer in jaren, maanden en weken (1j 3mnd 2w) in plaats van honderden weken.<br>De Franse versie van de kostencalculator werkt weer.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'sk', 'Čísla vo všetkých kalkulačkách sa teraz zapisujú podľa pravidiel jazyka stránky: v slovenskej verzii oddeľuje tisícky medzera (1 234 567) a desatinnú časť čiarka, aj v skrátenej podobe (1,5M). Bilióny majú vlastnú skratku, T (1,234T).<br>Čas kratší ako deň sa zobrazuje ako hodiny - 05:49:42 - a doba od jedného roka v rokoch, mesiacoch a týždňoch (1r 3m 2t) namiesto stoviek týždňov.<br>Francúzska verzia kalkulačky nákladov opäť funguje.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'tr', 'Tüm hesaplayıcılarda sayılar artık sitenin dilinin kurallarına göre yazılıyor: Türkçe sürümde binler nokta (1.234.567), ondalıklar virgülle ayrılıyor, kısaltılmış biçim de dahil (1,5M). Trilyonlar için ayrı bir kısaltma eklendi, T (1,234T).<br>Bir günden kısa süreler saat olarak gösteriliyor - 05:49:42 - bir yıl ve üzeri süreler ise yüzlerce hafta yerine yıl, ay ve hafta olarak (1y 3ay 2h).<br>Maliyet hesaplayıcısının Fransızca sürümü yeniden çalışıyor.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (77, 'bs', 'Brojevi se u svim kalkulatorima sada pišu po pravilima jezika stranice: u bosanskoj verziji hiljade se odvajaju tačkom (1.234.567), a decimale zarezom, i u skraćenom obliku (1,5M). Bilioni imaju vlastitu skraćenicu, T (1,234T).<br>Vrijeme kraće od jednog dana prikazuje se kao sat - 05:49:42 - a trajanje od godinu dana i duže u godinama, mjesecima i sedmicama (1g 3mj 2s) umjesto stotina sedmica.<br>Francuska verzija kalkulatora troškova ponovo radi.') on duplicate key update description = values(description);
